"""Summarize existing measurements plus isolated policy probes; no runtime tuning."""
from pathlib import Path
import hashlib,json,datetime
root=Path(__file__).resolve().parents[2]
out=root/'artifacts/latency-study'
def rows(name):
    return [json.loads(l) for l in (root/name).read_text().splitlines() if l.startswith('{')]
inputs=['artifacts/automated-acceptance.json','artifacts/soak-30min.jsonl','artifacts/call-soak-30min.jsonl','artifacts/latency-speaker-review/tts-latency.jsonl','artifacts/latency-study/policies.jsonl','artifacts/latency-speaker-review/short-cadence-trial/scenario-speech-noise.err','artifacts/latency-speaker-review/short-cadence-trial/conversation-golden.jsonl','engine/vad/VadSegmenter.hpp','engine/vad/VadWorker.cpp','engine/conversation/SegmentStabilityManager.hpp','engine/conversation/ConversationPipeline.cpp','engine/asr/ASRWorker.cpp','engine/asr/WhisperASR.cpp','engine/language/LanguageStabilizer.hpp','engine/audio/PCMPlayback.hpp','engine/common/BoundedQueue.hpp','third_party/webrtcvad/webrtc/common_audio/vad/vad_core.c','third_party/sherpa-onnx/sherpa-onnx/csrc/offline-tts-vits-impl.h','tools/diagnostics/LatencyPolicyStudy.cpp']
soak=rows(inputs[1])[-1];call=rows(inputs[2])[-1];tts=rows(inputs[3]);probe=rows(inputs[4]);trial=rows(inputs[6])[-1]
assert soak['result']==call['result']==probe[-1]['result']=='PASS'
summary=dict(createdAt=datetime.datetime.now(datetime.timezone.utc).isoformat(),scope='Study only. Existing recorded pipeline measurements; newly executed controlled policy probes. No production tuning or new E2E benchmark.',sourceFingerprint=json.loads((root/inputs[0]).read_text())['sourceFingerprint'],files={p:hashlib.sha256((root/p).read_bytes()).hexdigest() for p in inputs},baseline=dict(inPerson=dict(samples=soak['firstAudioSamples'],onsetToFirstAudioP50Ms=soak['firstAudioP50Ms'],onsetToFirstAudioP95Ms=soak['firstAudioP95Ms']),call=dict(outgoingP50Ms=call['outgoingFirstAudioP50Ms'],outgoingP95Ms=call['outgoingFirstAudioP95Ms'],incomingP50Ms=call['incomingFirstAudioP50Ms'],incomingP95Ms=call['incomingFirstAudioP95Ms']),tts=dict(samples=len(tts),inferenceRangeMs=[min(r['inferenceMs'] for r in tts),max(r['inferenceMs'] for r in tts)],loadRangeMs=[min(r['loadMs'] for r in tts),max(r['loadMs'] for r in tts)]),speechEndToFirstAudioMs=None),policyProbes=probe,illustrativeSharedASRUtilization=[dict(paths=2,assumedServiceMs=400,intervalMs=i,utilization=2*400/i) for i in (500,750,1000,1500)],rejectedTrial=dict(result=trial['result'],lastFirstAudioMs=trial.get('lastFirstAudioMs'),noiseError=(root/inputs[5]).read_text().strip()),targetStatus='NOT MEASURED / NOT IMPLEMENTED')
(out/'evidence.json').write_text(json.dumps(summary,indent=2,ensure_ascii=False)+'\n')
print(json.dumps({k:v for k,v in summary.items() if k not in ('files','policyProbes')},indent=2,ensure_ascii=False))
